{
  "paper_title": "An adaptive outlier removal aided k-means clustering algorithm",
  "authors_year": "Nawaf H.M.M. Shrifan, Muhammad F. Akbar, Nor Ashidi Mat Isa, 2022",
  "research_question": "How can clustering accuracy and centroid convergence of the k-means algorithm be improved in the presence of outliers and varying distance metrics?",
  "context": "K-means is widely used for data clustering but performs poorly when real-world datasets contain noise and outliers. Additionally, different distance metrics lead to variations in clustering accuracy. Improving k-means through outlier removal and distance metrics remains an active research topic.",
  "methods": [
    "Proposed an adapted Tukey's rule to eliminate outliers independently per attribute based on data skewness.",
    "Proposed a new distance metric combining ratio calculations, arctangent angles, and Root Mean Square Error (RMSE).",
    "Developed a modified k-means algorithm where centroids are updated using the average of lower and upper boundaries of outliers-free data without removing entire data points from clustering.",
    "Validated on nine standard multivariate datasets from the UCI machine learning repository and compared against conventional k-means, HCA, FFA, evolutionary algorithms (CPSO, CGA, SCMVO), DBSCAN, and k-means#."
  ],
  "main_findings": [
    "The modified k-means significantly improved overall clustering accuracy up to 80.57% on nine standard multivariate datasets.",
    "The adapted Tukey's rule reduced the overall iteration number for centroid convergence by approximately 50% compared to the standard Tukey's rule.",
    "The proposed distance metric outperformed standard Euclidean, cosine, and correlation metrics overall."
  ],
  "assumptions": [
    "Data points can be normalized to positive values between 1 and 90 to avoid division by zero.",
    "Tukey's constants r1 = 0.85 and r2 = 0.65 are globally effective across the tested datasets."
  ],
  "limitations_explicit": [
    "The outliers removal step adds extra processing time, making the modified k-means slower than conventional k-means for real-time clustering.",
    "The proposed distance metric is limited to real values greater than zero, requiring additional normalization processing time.",
    "High variety in the number of possible clusters (such as in the Blood dataset) degrades clustering accuracy using the modified k-means."
  ],
  "potential_open_questions": [
    {
      "question": "How can the time complexity of Tukey's rule for outlier removal be reduced to improve run-time for big data clustering?",
      "why_unresolved": "The adapted Tukey's rule adds extra processing time due to recursive attribute-wise checks.",
      "evidence": "Section 7 notes: 'improving the run-time of modified k-means for big data clustering will be investigated further in future work by reducing the time complexity of Tukey's rule for outlier removal.'",
      "sections": [
        "7. Conclusion and future work"
      ]
    }
  ],
